                "visualizaQuestao": "{\n  \"fonte\": \"\",\n  \"instrucao\": \"\",\n  \"textoBase\": \"<p style=\\\"margin-left: 0px !important;\\\">O Brexit foi definido por meio de um referendo realizado em 2016, no qual a população do Reino Unido decidiu, por maioria, pela saída da União Europeia. Esse processo refletiu divergências internas sobre economia, imigração e soberania nacional.</p>\",\n  \"comando\": \"<p style=\\\"margin-left: 0px !important;\\\">A realização do referendo sobre o Brexit evidencia:</p>\",\n  \"justificarFalsas\": false,\n  \"alternativas\": [\n    \"<p style=\\\"margin-left: 0px !important;\\\">o voto das minorias.<br></p>\",\n    \"<p style=\\\"margin-left: 0px !important;\\\">a decisão governamental.<br></p>\",\n    \"<p style=\\\"margin-left: 0px !important;\\\">uma consulta política nacional.<br></p>\",\n    \"<p style=\\\"margin-left: 0px !important;\\\">a participação direta da população nas tomadas de decisões.<br></p>\",\n    \"<p style=\\\"margin-left: 0px !important;\\\">utilização de mecanismos antidemocráticos da esquerda para decidir questões nacionais.</p>\"\n  ],\n  \"afirmacoes\": [],\n  \"associacoes\": null,\n  \"assercoes\": null\n}",
