                "visualizaQuestao": "{\n  \"fonte\": \"\",\n  \"instrucao\": \"\",\n  \"textoBase\": \"<p style=\\\"margin-left: 0px !important;\\\">As planícies europeias favorecem a entrada de massas de ar frio vindas do Ártico, enquanto as cadeias montanhosas dificultam a passagem dessas massas e bloqueiam a entrada de ar quente vindo do sul.</p>\",\n  \"comando\": \"<p style=\\\"margin-left: 0px !important;\\\">A influência do relevo europeu sobre o clima está associada:</p>\",\n  \"justificarFalsas\": false,\n  \"alternativas\": [\n    \"<p style=\\\"margin-left: 0px !important;\\\">às variações de altitudes.</p>\",\n    \"<p style=\\\"margin-left: 0px !important;\\\">as diferenças médias de temperaturas.</p>\",\n    \"<p style=\\\"margin-left: 0px !important;\\\">à localização e extensão geográfica, fato explicado pela distância latitudinal.</p>\",\n    \"<p style=\\\"margin-left: 0px !important;\\\">à atuação das formas de relevo na dinâmica das massas de ar e na definição climática.</p>\",\n    \"<p style=\\\"margin-left: 0px !important;\\\">à circulação de massas de ar que passam sem obstáculos pelas áreas de elevadas altitudes.</p>\"\n  ],\n  \"afirmacoes\": [],\n  \"associacoes\": null,\n  \"assercoes\": null\n}",
