                "visualizaQuestao": "{\n  \"fonte\": \"\",\n  \"instrucao\": \"\",\n  \"textoBase\": \"<p style=\\\"margin-left: 0px !important;\\\">O continente europeu apresenta grande diversidade climática, com a presença de climas como o polar, frio, temperado, semiárido e mediterrâneo, influenciados por fatores como latitude, proximidade do oceano e relevo.</p>\",\n  \"comando\": \"<p style=\\\"margin-left: 0px !important;\\\">A diversidade climática da Europa está relacionada principalmente:</p>\",\n  \"justificarFalsas\": false,\n  \"alternativas\": [\n    \"<p style=\\\"margin-left: 0px !important;\\\">à pouca variação da latitude.<br></p>\",\n    \"<p style=\\\"margin-left: 0px !important;\\\">a pouca oscilação da altitude.<br></p>\",\n    \"<p style=\\\"margin-left: 0px !important;\\\">à ação exclusivamente humana.<br></p>\",\n    \"<p style=\\\"margin-left: 0px !important;\\\">à combinação de fatores naturais e humanizados.<br></p>\",\n    \"<p style=\\\"margin-left: 0px !important;\\\">à interação entre latitude, relevo, maritimidade e massas de ar.</p>\"\n  ],\n  \"afirmacoes\": [],\n  \"associacoes\": null,\n  \"assercoes\": null\n}",
