                "visualizaQuestao": "{\n  \"fonte\": \"\",\n  \"instrucao\": \"\",\n  \"textoBase\": \"\",\n  \"comando\": \"<p style=\\\"margin-left: 0px !important;\\\">A União Europeia é um bloco econômico que apresenta elevado nível de integração entre seus países membros, envolvendo aspectos econômicos, políticos e sociais.</p><p style=\\\"margin-left: 0px !important;\\\">Cite duas das principais características da União Europeia.</p>\",\n  \"justificarFalsas\": false,\n  \"alternativas\": [],\n  \"afirmacoes\": [],\n  \"associacoes\": null,\n  \"assercoes\": null\n}",
