                "fonte": null,
                "visualizaResposta": "\n      <div style=\"background: #e0dede; border: 0px; padding: 1px 1px;\">\n        <span style=\"font-size: 12px\">\n          <strong>RESPOSTA</strong>\n        </span>\n      </div>\n      <div class=\"coluna-sm-12\">\n        <br>\n        <div><p style=\"margin-left: 0px !important;\">Porção de terras do continente que avançam sobre o mar ou o oceano, quase toda cercada por água.</p></div>\n        <br>\n      </div>\n    ",
